var SolutionBlock = class extends Block {
  static styleAttrs = ["uc-wgt-common"];
  requireCtxName = true;
  init$ = solutionBlockCtx(this);
  static _template = "";
  initCallback() {
    super.initCallback();
    this.a11y?.registerBlock(this);
  }
  static set template(value) {
    this._template = /* html */
    `${svg_sprite_default + value}<slot></slot>`;
  }
  static get template() {
    return this._template;
  }
};

