// src/blocks/CloudImageEditor/src/lib/classNames.ts
function normalize(...args) {
  return args.reduce((result, arg) => {
    if (typeof arg === "string") {
      result[arg] = true;
      return result;
    }
    for (const token of Object.keys(arg)) {
      result[token] = arg[token];
    }
    return result;
  }, {});
}
function classNames(...args) {
  const mapping2 = normalize(...args);
  return Object.keys(mapping2).reduce((result, token) => {
    if (mapping2[token]) {
      result.push(token);
    }
    return result;
  }, []).join(" ");
}
function applyClassNames(element, ...args) {
  const mapping2 = normalize(...args);
  for (const token of Object.keys(mapping2)) {
    element.classList.toggle(token, Boolean(mapping2[token]));
  }
}

// src/blocks/CloudImageEditor/src/lib/parseTabs.ts
var isTabIdValue = (value) => ALL_TABS.includes(value);
var parseTabs = (tabs) => {
  if (!tabs) {
    return ALL_TABS;
  }
  const tabList = deserializeCsv(tabs).filter(isTabIdValue);
  if (tabList.length === 0) {
    return ALL_TABS;
  }
  return tabList;
};

// src/blocks/CloudImageEditor/src/state.ts
function initState(fnCtx) {
  return {
    "*originalUrl": null,
    "*faderEl": null,
    "*cropperEl": null,
    "*imgEl": null,
    "*imgContainerEl": null,
    "*networkProblems": false,
    "*imageSize": null,
    "*editorTransformations": {},
    "*cropPresetList": [],
    "*currentAspectRatio": null,
    "*tabList": ALL_TABS,
    "*tabId": TabId.CROP,
    entry: null,
    extension: null,
    editorMode: false,
    modalCaption: "",
    isImage: false,
    msg: "",
    src: TRANSPARENT_PIXEL_SRC,
    fileType: "",
    showLoader: false,
    uuid: null,
    cdnUrl: null,
    cropPreset: "",
    tabs: serializeCsv([...ALL_TABS]),
    "presence.networkProblems": false,
    "presence.modalCaption": true,
    "presence.editorToolbar": false,
    "presence.viewerToolbar": true,
    // TODO: beware of wrong ctx in case of element re-creation:
    "*on.retryNetwork": () => {
      const images = fnCtx.querySelectorAll("img");
      for (const img of images) {
        const originalSrc = img.src;
        img.src = TRANSPARENT_PIXEL_SRC;
        img.src = originalSrc;
      }
      fnCtx.$["*networkProblems"] = false;
    },
    "*on.apply": (transformations) => {
      if (!transformations) {
        return;
      }
      const originalUrl = fnCtx.$["*originalUrl"];
      const cdnUrlModifiers = createCdnUrlModifiers(transformationsToOperations(transformations), "preview");
      const cdnUrl = createCdnUrl(originalUrl, cdnUrlModifiers);
      const eventData = {
        originalUrl,
        cdnUrlModifiers,
        cdnUrl,
        transformations
      };
      fnCtx.dispatchEvent(
        new CustomEvent("apply", {
          detail: eventData,
          bubbles: true,
          composed: true
        })
      );
      fnCtx.remove();
    },
    "*on.cancel": () => {
      fnCtx.remove();
      fnCtx.dispatchEvent(
        new CustomEvent("cancel", {
          bubbles: true,
          composed: true
        })
      );
    }
  };
}

