// src/blocks/CloudImageEditor/src/elements/slider/SliderUi.ts
var SliderUi = class extends Block {
  _observer;
  _thumbSize = 0;
  _zero = 0;
  _zeroDotEl;
  _stepsCount;
  constructor() {
    super();
    this.init$ = {
      ...this.init$,
      disabled: false,
      min: 0,
      max: 100,
      onInput: null,
      onChange: null,
      defaultValue: 0,
      "on.sliderInput": () => {
        const value = Number.parseInt(this._inputEl().value, 10);
        this._updateValue(value);
        this.$.onInput?.(value);
      },
      "on.sliderChange": () => {
        const value = Number.parseInt(this._inputEl().value, 10);
        this.$.onChange?.(value);
      }
    };
    this.setAttribute("with-effects", "");
  }
  initCallback() {
    super.initCallback();
    this.defineAccessor("disabled", (disabled) => {
      this.$.disabled = disabled;
    });
    this.defineAccessor("min", (min) => {
      this.$.min = min;
    });
    this.defineAccessor("max", (max) => {
      this.$.max = max;
    });
    this.defineAccessor("defaultValue", (defaultValue) => {
      this.$.defaultValue = defaultValue;
      const inputEl2 = this._inputEl();
      inputEl2.value = String(defaultValue);
      this._updateValue(defaultValue);
    });
    this.defineAccessor("zero", (zero) => {
      this._zero = zero;
    });
    this.defineAccessor("onInput", (onInput) => {
      if (!onInput) {
        return;
      }
      this.$.onInput = onInput;
    });
    this.defineAccessor("onChange", (onChange) => {
      if (!onChange) {
        return;
      }
      this.$.onChange = onChange;
    });
    this._updateSteps();
    this._observer = new ResizeObserver(() => {
      this._updateSteps();
      const value = Number.parseInt(this._inputEl().value, 10);
      this._updateValue(value);
    });
    this._observer.observe(this);
    this._thumbSize = Number.parseInt(window.getComputedStyle(this).getPropertyValue("--l-thumb-size"), 10);
    setTimeout(() => {
      const value = Number.parseInt(this._inputEl().value, 10);
      this._updateValue(value);
    }, 0);
    this.sub("disabled", (disabled) => {
      const el = this._inputEl();
      if (disabled) {
        el.setAttribute("disabled", "disabled");
      } else {
        el.removeAttribute("disabled");
      }
    });
    const inputEl = this._inputEl();
    inputEl.addEventListener("focus", () => {
      this.style.setProperty("--color-effect", "var(--hover-color-rgb)");
    });
    inputEl.addEventListener("blur", () => {
      this.style.setProperty("--color-effect", "var(--idle-color-rgb)");
    });
  }
  _inputEl() {
    return this.ref["input-el"];
  }
  _thumbEl() {
    return this.ref["thumb-el"];
  }
  _stepsEl() {
    return this.ref["steps-el"];
  }
  _updateValue(value) {
    this._updateZeroDot(value);
    const { width } = this.getBoundingClientRect();
    const slope = 100 / (this.$.max - this.$.min);
    const mappedValue = slope * (value - this.$.min);
    const offset = mappedValue * (width - this._thumbSize) / 100;
    window.requestAnimationFrame(() => {
      this._thumbEl().style.transform = `translateX(${offset}px)`;
    });
  }
  _updateZeroDot(value) {
    if (!this._zeroDotEl) {
      return;
    }
    this._zeroDotEl.style.opacity = value === this._zero ? "0" : "1";
    const { width } = this.getBoundingClientRect();
    const slope = 100 / (this.$.max - this.$.min);
    const mappedValue = slope * (this._zero - this.$.min);
    const offset = mappedValue * (width - this._thumbSize) / 100;
    window.requestAnimationFrame(() => {
      if (this._zeroDotEl) {
        this._zeroDotEl.style.transform = `translateX(${offset}px)`;
      }
    });
  }
  _updateSteps() {
    const STEP_GAP = 15;
    const stepsEl = this._stepsEl();
    const { width } = stepsEl.getBoundingClientRect();
    const half = Math.ceil(width / 2);
    const count = Math.ceil(half / STEP_GAP) - 2;
    if (this._stepsCount === count) {
      return;
    }
    const fragment = document.createDocumentFragment();
    const minorStepEl = document.createElement("div");
    const borderStepEl = document.createElement("div");
    minorStepEl.className = "uc-minor-step";
    borderStepEl.className = "uc-border-step";
    fragment.appendChild(borderStepEl);
    for (let i = 0; i < count; i += 1) {
      fragment.appendChild(minorStepEl.cloneNode());
    }
    fragment.appendChild(borderStepEl.cloneNode());
    for (let i = 0; i < count; i += 1) {
      fragment.appendChild(minorStepEl.cloneNode());
    }
    fragment.appendChild(borderStepEl.cloneNode());
    const zeroDotEl = document.createElement("div");
    zeroDotEl.className = "uc-zero-dot";
    fragment.appendChild(zeroDotEl);
    this._zeroDotEl = zeroDotEl;
    stepsEl.innerHTML = "";
    stepsEl.appendChild(fragment);
    this._stepsCount = count;
  }
  destroyCallback() {
    super.destroyCallback();
    this._observer?.disconnect();
  }
};
SliderUi.template = /* HTML */
`
  <div class="uc-steps" ref="steps-el"></div>
  <div ref="thumb-el" class="uc-thumb"></div>
  <input
    class="uc-input"
    type="range"
    ref="input-el"
    set="oninput: on.sliderInput; onchange: on.sliderChange; @min: min; @max: max; @value: defaultValue;"
  />
`;

// src/blocks/CloudImageEditorActivity/CloudImageEditorActivity.ts
var CloudImageEditorActivity = class extends UploaderBlock {
  couldBeCtxOwner = true;
  activityType = ActivityBlock.activities.CLOUD_IMG_EDIT;
  _entry;
  _instance;
  get activityParams() {
    const params = super.activityParams;
    if ("internalId" in params) {
      return params;
    }
    throw new Error(`Cloud Image Editor activity params not found`);
  }
  initCallback() {
    super.initCallback();
    this.registerActivity(this.activityType, {
      onActivate: () => this.mountEditor(),
      onDeactivate: () => this.unmountEditor()
    });
    this.subConfigValue("cropPreset", (cropPreset) => {
      if (this._instance && this._instance.getAttribute("crop-preset") !== cropPreset) {
        this._instance.setAttribute("crop-preset", cropPreset);
      }
    });
    this.subConfigValue("cloudImageEditorTabs", (tabs) => {
      if (this._instance && this._instance.getAttribute("tabs") !== tabs) {
        this._instance.setAttribute("tabs", tabs);
      }
    });
  }
  handleApply(e) {
    if (!this._entry) {
      return;
    }
    const result = e.detail;
    this._entry.setMultipleValues({
      cdnUrl: result.cdnUrl,
      cdnUrlModifiers: result.cdnUrlModifiers
    });
    this.modalManager?.close(ActivityBlock.activities.CLOUD_IMG_EDIT);
    this.historyBack();
  }
  handleCancel() {
    this.modalManager?.close(ActivityBlock.activities.CLOUD_IMG_EDIT);
    this.historyBack();
  }
  mountEditor() {
    const { internalId } = this.activityParams;
    const entry = this.uploadCollection.read(internalId);
    if (!entry) {
      throw new Error(`Entry with internalId "${internalId}" not found`);
    }
    this._entry = entry;
    const cdnUrl = this._entry.getValue("cdnUrl");
    if (!cdnUrl) {
      throw new Error(`Entry with internalId "${internalId}" hasn't uploaded yet`);
    }
    const instance = new CloudImageEditorBlock();
    const cropPreset = this.cfg.cropPreset;
    const tabs = this.cfg.cloudImageEditorTabs;
    instance.setAttribute("ctx-name", this.ctxName);
    instance.setAttribute("cdn-url", cdnUrl);
    if (cropPreset) {
      instance.setAttribute("crop-preset", cropPreset);
    }
    if (tabs) {
      instance.setAttribute("tabs", tabs);
    }
    instance.addEventListener("apply", (e) => {
      const customEvent = e;
      this.handleApply(customEvent);
      this.debugPrint(`editor event "apply"`, customEvent.detail);
    });
    instance.addEventListener("cancel", (e) => {
      const customEvent = e;
      this.handleCancel();
      this.debugPrint(`editor event "cancel"`, customEvent.detail);
    });
    instance.addEventListener("change", (e) => {
      const customEvent = e;
      this.debugPrint(`editor event "change"`, customEvent.detail);
    });
    this.innerHTML = "";
    this.appendChild(instance);
    this._instance = instance;
  }
  unmountEditor() {
    this._instance = void 0;
    this._entry = void 0;
    this.innerHTML = "";
  }
};

// src/utils/toKebabCase.ts
var toKebabCase = (str) => str.match(/[A-Z]{2,}(?=[A-Z][a-z]+[0-9]*|\b)|[A-Z]?[a-z]+[0-9]*|[A-Z]|[0-9]+/g)?.map((x) => x.toLowerCase()).join("-");

