// src/blocks/UrlSource/UrlSource.ts
var UrlSource = class extends UploaderBlock {
  couldBeCtxOwner = true;
  activityType = ActivityBlock.activities.URL;
  constructor() {
    super();
    this.init$ = {
      ...this.init$,
      importDisabled: true,
      onUpload: (event) => {
        event.preventDefault();
        this.telemetryManager.sendEvent({
          eventType: InternalEventType.ACTION_EVENT,
          payload: {
            metadata: {
              event: "upload-from-url",
              node: this.tagName
            }
          }
        });
        const url = this.ref.input["value"];
        this.api.addFileFromUrl(url, { source: UploadSource.URL });
        this.modalManager?.open(ActivityBlock.activities.UPLOAD_LIST);
        this.$["*currentActivity"] = ActivityBlock.activities.UPLOAD_LIST;
      },
      onCancel: () => {
        this.historyBack();
      },
      onInput: (event) => {
        const value = event.target?.value ?? "";
        this.set$({ importDisabled: !value });
      }
    };
  }
  initCallback() {
    super.initCallback();
    this.registerActivity(this.activityType ?? "", {
      onActivate: () => {
        const input = this.ref.input;
        input.value = "";
        input.focus();
      }
    });
  }
};
